mapper.select:
SELECT id, draft_id, agreement_type, scene, market, locale, brand_code, car_line_code, title, version,
       agreement_date, content_type, sanitizer_version, lock_version, create_by, create_time,
       modify_by, modify_time
FROM cms_agreement_draft


        AND agreement_type = #{criteria.agreementType}


        AND scene = #{criteria.scene}


        AND market = #{criteria.market}


        AND locale = #{criteria.locale}


        AND brand_code = #{criteria.brandCode}


        AND car_line_code = #{criteria.carLineCode}


        AND title LIKE CONCAT('%', #{criteria.title}, '%')


        AND version = #{criteria.version}


ORDER BY modify_time DESC, id DESC
